<?php
require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/functions.php';require_once dirname(__DIR__).'/includes/csrf.php';$u=require_login();verify_csrf();$pdo=db();$action=$_POST['action']??'';
if($action==='request'){$listing=(int)($_POST['listing_id']??0);$s=$pdo->prepare("SELECT id,user_id FROM listings WHERE id=? AND status='approved'");$s->execute([$listing]);$l=$s->fetch();if(!$l||(int)$l['user_id']===(int)$u['id']){flash('error','Trade request unavailable.');redirect('/listing.php?id='.$listing);} $q=$pdo->prepare("SELECT COUNT(*) FROM trade_requests WHERE listing_id=? AND buyer_id=? AND status IN ('requested','accepted')");$q->execute([$listing,$u['id']]);if($q->fetchColumn()){flash('error','You already have an active request for this listing.');redirect('/listing.php?id='.$listing);} $pdo->prepare('INSERT INTO trade_requests(listing_id,buyer_id,seller_id) VALUES(?,?,?)')->execute([$listing,$u['id'],$l['user_id']]);flash('success','Trade request sent.');redirect('/trade-requests.php');}
$id=(int)($_POST['trade_id']??0);$s=$pdo->prepare('SELECT * FROM trade_requests WHERE id=? AND (buyer_id=? OR seller_id=?)');$s->execute([$id,$u['id'],$u['id']]);$t=$s->fetch();if(!$t){http_response_code(403);exit('Trade not available.');}$new=null;if($action==='accept'&&(int)$t['seller_id']===(int)$u['id']&&$t['status']==='requested')$new='accepted';if($action==='reject'&&(int)$t['seller_id']===(int)$u['id']&&$t['status']==='requested')$new='rejected';if($action==='cancel'&&in_array($t['status'],['requested','accepted'],true))$new='cancelled';if($action==='complete'&&$t['status']==='accepted')$new='completed';if(!$new){flash('error','That trade transition is not allowed.');redirect('/trade-requests.php');}$pdo->beginTransaction();$pdo->prepare('UPDATE trade_requests SET status=?,updated_at=NOW() WHERE id=?')->execute([$new,$id]);if($new==='completed')$pdo->prepare("UPDATE listings SET status='removed',updated_at=NOW() WHERE id=?")->execute([$t['listing_id']]);$pdo->commit();flash('success','Trade updated to '.$new.'.');redirect('/trade-requests.php');